BEGIN;

CREATE TABLE IF NOT EXISTS "Saved_Color_Palettes" (
	"Saved_Color_Palette_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	"Clothing_Item_ID" BIGINT NOT NULL
		REFERENCES "Clothing_Items" ("Clothing_Item_ID") ON DELETE CASCADE,
	"ColorMagic_Palette_ID" VARCHAR(100) NOT NULL,
	"Palette_Name" VARCHAR(200) NOT NULL,
	"Colors" JSONB NOT NULL,
	"Tags" JSONB NOT NULL DEFAULT '[]'::JSONB,
	"Saved_At" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	CONSTRAINT "UQ_Saved_Color_Palettes_Item_Palette"
		UNIQUE ("Clothing_Item_ID", "ColorMagic_Palette_ID"),
	CONSTRAINT "CK_Saved_Color_Palettes_Colors_Array"
		CHECK (jsonb_typeof("Colors") = 'array'),
	CONSTRAINT "CK_Saved_Color_Palettes_Tags_Array"
		CHECK (jsonb_typeof("Tags") = 'array')
);

CREATE INDEX IF NOT EXISTS "IDX_Saved_Color_Palettes_Item_Saved_At"
	ON "Saved_Color_Palettes" ("Clothing_Item_ID", "Saved_At" DESC);

COMMIT;

SELECT count(*) AS saved_palette_count FROM "Saved_Color_Palettes";
